//! COMMISSION RESOLUTION against the shared contract -- which LEVEL a fill's per-lot rate comes from.
//!
//! `docs/contracts/ask-markup-vectors.json`'s `commissionResolution` array, generated by the web from
//! its own `lib/ask-markup.ts` (web branch feat/commission-resolution-vectors, fda06ee6, 13 cases).
//!
//! THIS TEST IS AT THE RESOLUTION LEVEL ON PURPOSE, and that is the whole point of it. The engine
//! already had a commission contract -- `open-chain-vector.json`, asserted in `order_book_prisma_db` --
//! and it was green the entire time the engine was undercharging every commission-priced group. It
//! could not have failed: its generator passes the per-lot rate INTO
//! `lib/dealing.ts openPositionFromOrder` as an argument, and the engine-side fixture seeds that same
//! number straight into `"BrokerSymbol"`. Both sides are handed the answer, so the vector pins the
//! ledger CHAIN (amount, balance, note, deal) and can never pin the LEVEL the rate was read from.
//! A chain test cannot catch a hierarchy bug; only this can.
//!
//! No database: `commission::resolve_per_lot` is a pure function over the four levels, so the levels
//! are built straight from the vector. The DB half -- that the three columns are actually SELECTED and
//! decoded into those levels -- is covered by the open snapshot's own tests and by the live fill.

use order_management::commission::{resolve_per_lot, CommissionLevels};
use rust_decimal::Decimal;
use std::str::FromStr;

fn vectors() -> serde_json::Value {
    let path = concat!(env!("CARGO_MANIFEST_DIR"), "/../../docs/contracts/ask-markup-vectors.json");
    serde_json::from_str(&std::fs::read_to_string(path).expect("ask-markup-vectors.json")).unwrap()
}

fn dec(v: &serde_json::Value) -> Decimal {
    Decimal::from_str(v.as_str().expect("decimal string")).expect("parses")
}

/// A level as the contract expresses it:
///   `null`                        -- no row at all
///   `{"commissionPerLot": null}`  -- the row exists, the column is null
///   `{"commissionPerLot": "2.5"}` -- set
/// The first two are both a SQL NULL to the engine and so both `None`; the contract's wording is "per
/// field, a null falls through EVEN WHEN THE ROW EXISTS", and `a_null_row_and_no_row_agree` below pins
/// that the two shapes really are indistinguishable rather than merely both happening to work here.
fn level(v: &serde_json::Value) -> Option<Decimal> {
    if v.is_null() {
        return None;
    }
    match &v["commissionPerLot"] {
        serde_json::Value::Null => None,
        x => Some(dec(x)),
    }
}

#[test]
fn every_commission_resolution_vector_picks_the_level_the_web_picks() {
    let v = vectors();
    let cases = v["commissionResolution"].as_array().expect("commissionResolution");
    // Pinned like the other two arrays in this file: a regenerated contract with more or fewer cases
    // must be re-read, not quietly covered less.
    assert_eq!(cases.len(), 13, "the contract file changed: re-check the engine's commission resolution against it");

    let mut on = 0;
    let mut off = 0;
    for c in cases {
        let name = c["name"].as_str().unwrap();
        let levels = CommissionLevels {
            pricing_engine: c["pricingEngineEnabled"].as_bool().expect("pricingEngineEnabled"),
            account_symbol: level(&c["accountSymbol"]),
            group: level(&c["group"]),
            broker: dec(&c["broker"]),
        };
        if levels.pricing_engine { on += 1 } else { off += 1 }

        let got = resolve_per_lot(&levels);
        let want = dec(&c["expected"]["commissionPerLot"]);
        assert_eq!(got.normalize(), want.normalize(), "{name}: resolved {got}, the web resolves {want}");

        // charge = rate x volume, UNROUNDED (the contract's own words). record_commission multiplies
        // exactly this way and declines to write anything <= 0.
        let charge = got * dec(&c["volume"]);
        let want_charge = dec(&c["expected"]["charge"]);
        assert_eq!(charge.normalize(), want_charge.normalize(), "{name}: charge {charge}, expected {want_charge}");
        if want_charge <= Decimal::ZERO {
            assert!(charge <= Decimal::ZERO, "{name}: a zero charge must stay zero, so nothing is written");
        }
    }
    // both switch states must really be exercised, or half the rule is untested
    assert!(on >= 5 && off >= 4, "expected both pricing-engine states in the contract, got on={on} off={off}");
}

/// The rule the hierarchy exists for, asserted independently of the table: with the pricing engine OFF
/// the account-symbol level is not merely outranked, it is NOT CONSULTED. The contract's case
/// "engine off: account-symbol config is ignored" covers one instance; this covers the shape, so a
/// future refactor that starts honouring it when the engine is off fails here even if that one case is
/// edited away.
#[test]
fn with_the_pricing_engine_off_the_account_symbol_level_does_not_exist() {
    let base = CommissionLevels {
        pricing_engine: false,
        account_symbol: Some(Decimal::from(1)),
        group: Some(Decimal::from_str("2.5").unwrap()),
        broker: Decimal::from(7),
    };
    assert_eq!(resolve_per_lot(&base), Decimal::from_str("2.5").unwrap(), "the group wins while the engine is off");
    // and with no group, it falls to the BROKER -- not to the account-symbol value sitting right there
    let no_group = CommissionLevels { group: None, ..base };
    assert_eq!(resolve_per_lot(&no_group), Decimal::from(7), "with no group it is the broker, never the account-symbol");
    // turning the engine on is the only thing that changes
    let engine_on = CommissionLevels { pricing_engine: true, ..no_group };
    assert_eq!(resolve_per_lot(&engine_on), Decimal::from(1), "with the engine on the account-symbol finally counts");
}

/// "A null falls through even when the row exists": a row whose column is null must be
/// indistinguishable from no row at all. Both reach the engine as a SQL NULL, and this pins that the
/// resolver never gets a chance to tell them apart.
#[test]
fn a_null_row_and_no_row_agree() {
    let v = vectors();
    let cases = v["commissionResolution"].as_array().unwrap();
    // the contract supplies both shapes; every "row exists, column null" case must resolve exactly as
    // the same case with the row removed
    let mut checked = 0;
    for c in cases {
        if c["group"].is_null() || !c["group"]["commissionPerLot"].is_null() {
            continue;
        }
        let with_null_row = CommissionLevels {
            pricing_engine: c["pricingEngineEnabled"].as_bool().unwrap(),
            account_symbol: level(&c["accountSymbol"]),
            group: level(&c["group"]),
            broker: dec(&c["broker"]),
        };
        let with_no_row = CommissionLevels { group: None, ..with_null_row };
        assert_eq!(
            resolve_per_lot(&with_null_row),
            resolve_per_lot(&with_no_row),
            "{}: a null group commission must behave exactly like no group row",
            c["name"].as_str().unwrap()
        );
        checked += 1;
    }
    assert!(checked >= 2, "expected the contract to carry null-column group rows, found {checked}");
}

/// An explicit 0 is a real zero, at either level -- the "VIP zero, not unset" case. Asserted as a
/// shape too, because this is the one that a `COALESCE(..., 0)` or an `unwrap_or_default()` in the SQL
/// would silently destroy: the value and the fallback would become the same thing.
#[test]
fn an_explicit_zero_outranks_the_level_below_it() {
    let group_zero = CommissionLevels {
        pricing_engine: false,
        account_symbol: None,
        group: Some(Decimal::ZERO),
        broker: Decimal::from(7),
    };
    assert_eq!(resolve_per_lot(&group_zero), Decimal::ZERO, "a group's explicit 0 is not 'unset'");
    let acct_zero = CommissionLevels {
        pricing_engine: true,
        account_symbol: Some(Decimal::ZERO),
        group: Some(Decimal::from(2)),
        broker: Decimal::from(7),
    };
    assert_eq!(resolve_per_lot(&acct_zero), Decimal::ZERO, "an account-symbol's explicit 0 beats the group");
}
